mily: \'Georgia\', serif;\\r\\n}\\r\\n\\r\\n\\/* Conteneur principal du slider *\\/\\r\\n.slider_complet {\\r\\n  position: relative;\\r\\n  width: 100%;\\r\\n  overflow: hidden;\\r\\n}\\r\\n\\r\\n\\/* Piste o\\u00f9 d\\u00e9file le slider *\\/\\r\\n.slide_piste {\\r\\n  position: relative;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n\\/* Tous les slides sont cach\\u00e9s par d\\u00e9faut *\\/\\r\\n.slide {\\r\\n  display: none;\\r\\n  position: relative;\\r\\n  width: 100%;\\r\\n}\\r\\n\\r\\n\\/* Slide actif visible *\\/\\r\\n.slide_active {\\r\\n  display: block;\\r\\n  position: relative;\\r\\n  width: 100%;\\r\\n  animation: fadeIn 0.5s ease;\\r\\n}\\r\\n\\r\\n\\/* Image de fond avec d\\u00e9cors et illustrations *\\/\\r\\n.slide_decor {\\r\\n  width: 100%;\\r\\n  height: auto;\\r\\n  display: block;\\r\\n}\\r\\n\\r\\n\\/* Bouteille superpos\\u00e9e par-dessus le d\\u00e9cor *\\/\\r\\n.slide_bouteille {\\r\\n  position: absolute;\\r\\n  top: 50%;\\r\\n  left: 55%;\\r\\n  transform: translate(-50%, -50%);\\r\\n  height: 100%;\\r\\n  width: auto;\\r\\n  max-height: 800px;\\r\\n  pointer-events: none;\\r\\n}\\r\\n\\r\\n\\/* Barre de navigation *\\/\\r\\n.slide_navigation {\\r\\n  display: flex;\\r\\n  align-items: stretch; \\/* les \\u00e9l\\u00e9ments s\'\\u00e9tirent \\u00e0 la m\\u00eame hauteur *\\/\\r\\n  justify-content: center;\\r\\n  \\r\\n  padding: 20px 0;\\r\\n  margin-left: 100px;\\r\\n}\\r\\n\\r\\n\\/* Boutons fl\\u00e8ches *\\/\\r\\n.bouton_navigation {\\r\\n  background: #1A2A6C;\\r\\n  border: none;\\r\\n  width: 20px;\\r\\n  cursor: pointer;\\r\\n  display: flex;\\r\\n  align-items: center;\\r\\n  justify-content: center;\\r\\n}\\r\\n\\r\\n.bouton_navigation img {\\r\\n  width: 100%;\\r\\n  height: auto;\\r\\n  \\r\\n}\\r\\n\\r\\n\\/* Bouton D\\u00c9COUVRIR LA CUV\\u00c9E *\\/\\r\\n.decouverte_cuvee {\\r\\n  font-size: 30px;\\r\\n  font-family: \'Fira Sans\', \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\\r\\n  letter-spacing: 3px;\\r\\n  color: #FF