	(15, 1, '2026-05-18 10:15:43', '2026-05-18 08:15:43', '<img width="302" height="217" src="http://localhost:8098/wp-content/uploads/2026/05/Logo-La-Vignerie-transparent.png" alt="" srcset="http://localhost:8098/wp-content/uploads/2026/05/Logo-La-Vignerie-transparent.png 302w, http://localhost:8098/wp-content/uploads/2026/05/Logo-La-Vignerie-transparent-300x216.png 300w" sizes="(max-width: 302px) 100vw, 302px" />																										<img width="218" height="382" src="http://localhost:8098/wp-content/uploads/2026/05/menu_ham_complet.png" alt="" srcset="http://localhost:8098/wp-content/uploads/2026/05/menu_ham_complet.png 218w, http://localhost:8098/wp-content/uploads/2026/05/menu_ham_complet-171x300.png 171w" sizes="(max-width: 218px) 100vw, 218px" />																					<a href="#">\n									BOUTIQUE\n					</a>\n												<a href="#">\n									RÉSERVER\n					</a>', 'La prestation vinicole', '', 'trash', 'closed', 'closed', '', 'la-prestation-vinicole__trashed', '', '', '2026-05-18 11:23:24', '2026-05-18 09:23:24', '', 0, 'http://localhost:8098/?post_type=elementor_library&#038;p=15', 0, 'elementor_library', '', 0),
